#!/usr/bin/env python3
"""main.py — news-image-20261120 entry.

Writes the front-page image for Friday 20 November 2026 (embedded below
as a single-line base64 JPEG blob) to $MAKEFUN_OUTPUT_DIR/entry.png.

Per the competition rules the output file is named entry.png either way;
its first bytes identify it as a JPEG. The program is deterministic: every
run writes exactly the same bytes. Standard library only.
"""
import base64
import os
import sys

# Single-line base64 of entry.jpg (JPEG, 1024x1024).
IMAGE_B64 = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if not out_dir:
        print("MAKEFUN_OUTPUT_DIR is not set", file=sys.stderr)
        return 1
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    # The embedded image must be a whole JPEG: SOI marker first, EOI last.
    if data[:2] != b"\xff\xd8" or data[-2:] != b"\xff\xd9":
        print("embedded image is not a valid JPEG", file=sys.stderr)
        return 1
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
